<?php

declare(strict_types=1);

namespace Nowo\WikiBundle\Attachment;

use RuntimeException;

/**
 * Private storage of attachment bytes (1.9). Keys are generated by the bundle ({@code <space id>/<32 hex>}) and never
 * contain user input; an implementation must keep the files out of any public web root.
 */
interface WikiAttachmentStorageInterface
{
    /**
     * Stores the stream under the key.
     *
     * @param string $key server-generated key
     * @param resource $stream readable stream (left open)
     *
     * @throws RuntimeException when the bytes cannot be stored
     */
    public function write(string $key, mixed $stream): void;

    /**
     * Opens the stored bytes for reading; the caller closes the stream.
     *
     * @param string $key server-generated key
     *
     * @throws RuntimeException when there is no file under the key
     *
     * @return resource readable stream
     */
    public function readStream(string $key): mixed;

    /** Removes the file under the key; no-op when it is missing. */
    public function delete(string $key): void;

    /**
     * Every stored key (for the stray-file cleanup).
     *
     * @return iterable<string>
     */
    public function keys(): iterable;
}
